(()=>{'use strict';
 const C=ListeningFullTestCore,$=id=>document.getElementById(id),storage=localStorage;
 let set,frames=[],active=0,current=1,started=false,done=false,transitioning=false,starting=false,last=performance.now(),saving=false,unloading=false,footerSignature='';
 const api=i=>frames[i]?.contentWindow?.ListeningFrame;
 const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const snapshots=()=>frames.map((_,i)=>api(i)?.snapshot()||set.snapshots?.[i]||{});
 function persist(){if(!set||done)return;try{set.snapshots=snapshots();set.active=active;set.current=current;storage.setItem(C.key,JSON.stringify(set))}catch{}}
 function saveSoon(){if(saving)return;saving=true;queueMicrotask(()=>{saving=false;persist();paint()})}
 function answered(i,n){return !!String(api(i)?.snapshot().answers[n]??'').trim()}
 function navigate(n){if(n<1||n>40)return;active=Math.floor((n-1)/10);current=n;frames.forEach((f,i)=>f.hidden=i!==active);paint();api(active)?.focus(n);persist()}
 function remaining(){if(!set)return 0;if(set.phase==='review')return set.reviewLeft;return frames.reduce((sum,_,i)=>i<set.audioIndex?sum:sum+Math.max(0,api(i).duration-(i===set.audioIndex?(api(i).audio.currentTime||0):0)),120)}
 function clock(){if(!set||frames.some((_,i)=>!api(i)))return;const seconds=Math.max(0,Math.ceil(remaining()));$('timer').textContent=Math.floor(seconds/60)+':'+String(seconds%60).padStart(2,'0');$('audio-status').textContent=done?'Test completed':set.phase==='review'?'Check your answers':started?'◖ Audio is Playing · Part '+(set.audioIndex+1):'4 parts · 40 questions'}
 function paint(){if(!set)return;const signature=JSON.stringify([active,current,started,done,snapshots().map(s=>s.answers)]);if(signature===footerSignature){clock();return}footerSignature=signature;const footer=$('footer');footer.innerHTML=set.items.map((item,i)=>{const count=Array.from({length:10},(_,j)=>i*10+j+1).filter(n=>answered(i,n)).length;return `<div data-part="${i}" class="part-nav ${i===active?'active':''} ${count===10?'complete':''}" style="--progress:${count*10}%"><span class="label-progress"></span><button class="part-label" data-part="${i}" aria-label="View Part ${i+1}">Part ${i+1}</button>${i===active?`<div class="dots">${Array.from({length:10},(_,j)=>{const n=i*10+j+1;return `<button class="dot ${n===current?'current':''} ${answered(i,n)?'answered':''}" data-go="${n}" aria-label="Question ${n}${answered(i,n)?', answered':''}">${n}</button>`}).join('')}</div>`:`<span class="count">${count} of 10</span>`}</div>`}).join('')+`<button class="submit-tick" aria-label="Submit answers" ${done||!started?'disabled':''}>✓</button>`;footer.onclick=e=>{const go=e.target.closest('[data-go]'),part=e.target.closest('[data-part]');if(go)navigate(+go.dataset.go);else if(e.target.closest('.submit-tick'))requestSubmit();else if(part)navigate(+part.dataset.part*10+1)};document.querySelector('.nav-prev').disabled=current===1;document.querySelector('.nav-next').setAttribute('aria-label',current===40?'Submit answers':'Next question');clock()}
 function block(message){if(unloading||done||!started)return;$('audio-message').textContent=message;$('audio-block').hidden=false;clock()}
 async function playAudio(){if(done||starting||set.phase==='review')return;starting=true;try{if(api(set.audioIndex).audio.error)api(set.audioIndex).audio.load();await api(set.audioIndex).start();if(!api(set.audioIndex).state.started||api(set.audioIndex).audio.paused)throw Error('Audio could not start');$('audio-block').hidden=true}catch{block('Audio could not start. Click Continue audio to resume.')}finally{starting=false;persist();clock()}}
 async function advance(i){if(done||!started||transitioning||set.phase!=='playing'||i!==set.audioIndex)return;transitioning=true;try{if(i<3){set.audioIndex=i+1;navigate((i+1)*10+1);persist();await playAudio()}else{set.phase='review';set.reviewLeft=120;last=performance.now();$('audio-block').hidden=true;persist();clock()}}finally{transitioning=false}}
 async function start(){if(started||done)return;$('play').disabled=true;started=true;set.phase=set.phase==='review'?'review':'playing';last=performance.now();$('start-overlay').hidden=true;paint();persist();if(set.phase==='playing')await playAudio()}
 function requestSubmit(){if(!started||done)return;$('submit-count').textContent=frames.reduce((sum,_,i)=>sum+Array.from({length:10},(_,j)=>i*10+j+1).filter(n=>answered(i,n)).length,0)+' of 40 answered';$('submit-dialog').showModal()}
 function submit(automatic=false){if(done||!started)return;const saved=snapshots();try{C.submit(storage,set,saved,automatic)}catch{block('Could not save your answers. Please try submitting again.');return}done=true;started=false;set.submitted=true;if($('submit-dialog').open)$('submit-dialog').close();$('audio-block').hidden=true;frames.forEach((_,i)=>api(i).finish());const count=saved.reduce((sum,s)=>sum+Object.values(s.answers||{}).filter(x=>String(x??'').trim()).length,0);$('summary').innerHTML='<h1>Your answers have been submitted</h1><p>'+count+' of 40 answered</p><p>Bạn có thể xem lại câu trả lời để tự đối chiếu.</p><div class="actions"><button id="review">Review answers</button><a href="listening.html">‹ Listening</a></div>'+set.items.map((item,i)=>'<h2>Part '+(i+1)+' — '+escape(item.title)+'</h2><table><thead><tr><th>Question</th><th>Your answer</th></tr></thead><tbody>'+api(i).answers().map(a=>'<tr><td>'+a.n+'</td><td>'+escape(a.text)+'</td></tr>').join('')+'</tbody></table>').join('');$('summary').hidden=false;$('review').onclick=()=>{$('summary').hidden=true;navigate(current)};paint();clock()}
 function fail(message){$('load-message').textContent=message||'Không tải được đề Listening. Vui lòng thử lại.';$('reload').hidden=false;$('loading').hidden=false}
 async function loadFrame(item,i){const f=document.createElement('iframe');f.title='Part '+(i+1)+' — '+item.title;f.allow='autoplay';f.hidden=i!==active;frames[i]=f;return new Promise((resolve,reject)=>{let poll;const timeout=setTimeout(()=>{clearInterval(poll);reject(Error('Frame timeout'))},45000);f.onload=()=>{poll=setInterval(()=>{const a=api(i);if(!a)return;clearInterval(poll);clearTimeout(timeout);resolve()},30)};f.onerror=()=>{clearTimeout(timeout);reject(Error('Frame failed'))};const u=new URL(item.url,location.href);u.searchParams.set('full','1');f.src=u.pathname+u.search;$('full-frames').append(f)})}
 window.addEventListener('message',e=>{if(e.origin!==location.origin||!set)return;const i=frames.findIndex(f=>f.contentWindow===e.source);if(i<0)return;if(e.data?.type==='listening-audio-ended')advance(i);if(e.data?.type==='listening-submit-request')requestSubmit()});
 window.addEventListener('pagehide',()=>{unloading=true;if(started&&set.phase==='review'){set.reviewLeft=Math.max(0,set.reviewLeft-(performance.now()-last)/1000);last=performance.now()}persist();started=false;frames.forEach((_,i)=>api(i)?.audio.pause())});
 window.addEventListener('pageshow',e=>{if(e.persisted&&set&&!done){unloading=false;started=false;$('start-overlay').hidden=false;$('play').disabled=false;$('play').focus();clock()}});
 $('play').disabled=true;$('play').onclick=start;$('continue-audio').onclick=playAudio;$('reload').onclick=()=>location.reload();$('cancel-submit').onclick=()=>$('submit-dialog').close();$('confirm-submit').onclick=()=>submit(false);document.querySelector('.nav-prev').onclick=()=>navigate(current-1);document.querySelector('.nav-next').onclick=()=>current===40?requestSubmit():navigate(current+1);
 const icons=[...document.querySelectorAll('.nav-icons>svg')];icons[2]?.addEventListener('click',()=>frames[active].contentDocument.querySelector('.nav-icons>svg[aria-label="Options"]')?.dispatchEvent(new Event('click')));icons[3]?.addEventListener('click',()=>frames[active].contentWindow.IELTSAnnotations?.toggle());
 setInterval(()=>{const now=performance.now();if(started&&!done&&set.phase==='review'){set.reviewLeft=Math.max(0,set.reviewLeft-(now-last)/1000);if(set.reviewLeft<=0)submit(true)}last=now;if(set&&!done&&started){clock();persist()}},1000);
 (async()=>{try{const r=await fetch('listening-catalog.json',{cache:'no-cache'});if(!r.ok)throw Error('Catalog');const catalog=await r.json(),draft=C.read(storage,C.key,null),resume=new URLSearchParams(location.search).get('resume')==='1';set=resume&&C.valid(catalog,draft)?draft:{id:crypto.randomUUID(),items:C.select(catalog,storage),audioIndex:0,phase:'ready',reviewLeft:120,snapshots:[],active:0,current:1};set.items=set.items.map(item=>catalog.find(c=>c.id===item.id));active=Number.isInteger(set.active)&&set.active>=0&&set.active<4?set.active:0;current=Number.isInteger(set.current)&&set.current>=1&&set.current<=40?set.current:active*10+1;
 await Promise.all(set.items.map(loadFrame));await Promise.all(frames.map((_,i)=>api(i).restore(set.snapshots?.[i])));
 frames.forEach((f,i)=>{const doc=f.contentDocument;for(const name of ['input','change','click','pointerup','focusin'])doc.getElementById('qpanel').addEventListener(name,e=>{const n=Number(e.target.closest('[data-q]')?.dataset.q);if(i===active&&n>i*10&&n<=i*10+10)current=n;saveSoon()});const audio=api(i).audio;audio.addEventListener('playing',()=>{if(i===set.audioIndex){$('audio-block').hidden=true;clock()}});audio.addEventListener('waiting',()=>{if(i===set.audioIndex)block('Audio is loading. Your timer is paused.')});audio.addEventListener('error',()=>{if(i===set.audioIndex)block('The audio could not be loaded. Click Continue audio to retry.')})});
 $('loading').hidden=true;$('play').disabled=false;paint();persist();$('play').focus();
 }catch(e){fail()}})();
 window.ListeningFullTest={get state(){return {set,started,done,current,active}},navigate,submit,snapshots};
})();
